return {rwnpc01={id="rwnpc01",dsc="他蒙着面，看不清楚长相，看着像个男子。",sex="野兽",age=30,looks=18,showequip={},withCorpse=0},rwnpc02={id="rwnpc02",dsc="她蒙着面，看不清楚长相，看着像个女子。",sex="野兽",age=28,looks=22,showequip={},withCorpse=0},rwnpc03={id="rwnpc03",dsc="她一身白色的窄袖劲装，玉雕的长笛斜悬腰间，眉间似凝着霜雪，透着一丝孤傲。",sex="女",age=28,looks=22,showequip={},withCorpse=0},rwnpc04={id="rwnpc04",dsc="他一袭青衫在身，轻执一把折扇，扇面开合之间，似有清风徐来，给人的感觉甚是亲切。",sex="男",age=30,looks=23,showequip={},withCorpse=0},rwnpc05={id="rwnpc05",dsc="他应当是华山的弟子，面上还有些稚嫩，眼睛清澈明亮，透着一股青涩的倔强。",sex="男",age=17,looks=20,showequip={},withCorpse=0},rwnpc06={id="rwnpc06",dsc="这镇上寻常人家的孩子，一身的粗布衣衫虽显朴素，却浆洗得干干净净，乌溜溜的眼睛透着灵动劲儿。",sex="男",age=10,looks=20,showequip={},withCorpse=0},rwnpc07={id="rwnpc07",dsc="镇上人家的小女娃，身上的衣物样式简单朴素，却也整洁合身。此刻，她圆润的小脸上还带着未干的泪痕，委屈的模样惹人怜爱。",sex="女",age=10,looks=21,showequip={},withCorpse=0},rwnpc08={id="rwnpc08",dsc="他发须皆白如雪，双眸却依旧明亮有神，整个人看起来精神奕奕。",sex="男",age=60,looks=17,showequip={},withCorpse=0},rwnpc09={id="rwnpc09",dsc="他身着一袭蓝色布衣，端坐在老旧的柜台后面，双手熟练地在算盘上翻飞，珠子碰撞发出清脆的声响。",sex="男",age=30,looks=20,showequip={},withCorpse=0},rwnpc10={id="rwnpc10",dsc="他穿着一件绣着锦鲤的红肚兜，小胳膊就像一节鲜嫩的藕段，虎头虎脑的模样甚是可爱。",sex="男",age=12,looks=20,showequip={},withCorpse=0},rwnpc11={id="rwnpc11",dsc="他应当是华山的弟子，却是一副懒懒散散的模样，随意的抱着长剑，剑柄上的穗子都透着懒散。",sex="男",age=24,looks=20,showequip={},withCorpse=0},rwnpc12={id="rwnpc12",dsc="皇帝最宠爱的小女儿，与福王平王一起长大，喜欢舞刀弄枪。",sex="女",age=20,looks=27,showequip={},withCorpse=0},rwnpc13={id="rwnpc13",dsc="他是一位白须白眉的老僧，身穿一袭银丝棕黄袈裟。他身材甚高，但骨瘦如柴，顶门高耸，双目湛然有神。",sex="男",age=70,looks=30,showequip={},withCorpse=0},rwnpc14={id="rwnpc14",dsc="峨眉派现任掌门，为人刚正不阿嫉恶如仇，一心要将峨眉一派发扬光大，她的武功已臻化境，江湖之中罕有敌手。",sex="女",age=52,looks=20,showequip={},withCorpse=0},rwnpc15={id="rwnpc15",dsc="上官林之女，财神帮帮主。她智慧绝伦，以女流之躯经营庞大的财神帮，并开始开拓海外贸易。好收集奇珍异宝，富可敌国。武功习自其父，虽身手了得，但凡事都喜欢用金钱来解决，不喜动武。",sex="女",age=23,looks=26,showequip={},withCorpse=0},rwnpc16={id="rwnpc16",dsc="他看上去颇为年轻，是中原武林的年轻一代弟子。",sex="男",age=20,looks=19,showequip={},withCorpse=0},rwnpc17={id="rwnpc17",dsc="落月山庄的一名弟子。目若秋水，风度翩翩，笑容让人捉摸不定。",sex="男",age=26,looks=25,showequip={},withCorpse=0},rwnpc18={id="rwnpc18",dsc="一个满脸风霜的汉子，双手布满老茧，正倚在褪色的马车旁抽着旱烟。",sex="男",age=34,looks=17,showequip={},withCorpse=0},rwnpc19={id="rwnpc19",dsc="他看起来饱经风霜，站在一个坟墓前，正缓缓的摆着供品。",sex="男",age=47,looks=19,showequip={},withCorpse=0},rwnpc20={id="rwnpc20",dsc="他是附近的村民。",sex="男",age=35,looks=17,showequip={},withCorpse=0},rwnpc21={id="rwnpc21",dsc="他是附近的村民。",sex="男",age=56,looks=17,showequip={},withCorpse=0},rwnpc22={id="rwnpc22",dsc="此人看起来手脚非常麻利。",sex="男",age=24,looks=17,showequip={},withCorpse=0},rwnpc23={id="rwnpc23",dsc="他看起来是用拳的高手。",sex="男",age=33,looks=19,showequip={},withCorpse=0},rwnpc24={id="rwnpc24",dsc="他就是茶馆的老板。",sex="男",age=45,looks=17,showequip={},withCorpse=0},rwnpc25={id="rwnpc25",dsc="她是落月山庄弟子，年纪轻轻武功十分不凡，她身穿一袭红衣，煞是惹眼。",sex="女",age=20,looks=23,showequip={},withCorpse=0},rwnpc26={id="rwnpc26",dsc="莫灵儿是华山掌门莫天雄的独生女儿。",sex="女",age=20,looks=25,showequip={},withCorpse=0},rwnpc27={id="rwnpc27",dsc="他是附近的村民。",sex="男",age=43,looks=17,showequip={},withCorpse=0},rwnpc28={id="rwnpc28",dsc="他是附近的村民。",sex="男",age=46,looks=17,showequip={},withCorpse=0},rwnpc29={id="rwnpc29",dsc="她面前摆着不少青菜，每个都青翠鲜嫩。",sex="女",age=56,looks=16,showequip={},withCorpse=0},rwnpc30={id="rwnpc30",dsc="一个四十七八岁的汉子，挽着裤腿站在腥湿的木盆旁，十指被水泡得发白，正低头刮着鱼鳞。",sex="男",age=47,looks=17,showequip={},withCorpse=0},rwnpc31={id="rwnpc31",dsc="她一身粗布衣裳，挎着个篮子，篮子里装了不少东西。",sex="女",age=48,looks=19,showequip={},withCorpse=0},rwnpc32={id="rwnpc32",dsc="他是一位胖乎乎的汉子，腰间的围裙还沾着油渍。",sex="男",age=30,looks=15,showequip={},withCorpse=0},rwnpc33={id="rwnpc33",dsc="此人头戴斗笠看不清面容，但其气息内敛，应当是个高手。",sex="野兽",age=30,looks=17,showequip={},withCorpse=0},rwnpc34={id="rwnpc34",dsc="此人头戴斗笠看不清面容，但其气息内敛，应当是个高手。",sex="野兽",age=30,looks=17,showequip={},withCorpse=0},rwnpc35={id="rwnpc35",dsc="他是天狼教近些年来崛起的高手。他为人行事高调，自诩风流倜傥，喜欢手执一柄白扇、以读书人的装扮示人，人称天狼妖人白扇子。",sex="男",age=32,looks=28,showequip={},withCorpse=0},rwnpc36={id="rwnpc36",dsc="虚渺宫四师姐，清竹子特别传授其掌法，配合无双的虚步太清，于近身徒手别有轻灵味道。",sex="女",age=20,looks=25,showequip={},withCorpse=0},rwnpc37={id="rwnpc37",dsc="峨眉“三剑”之一，面容姣好，武功不凡。",sex="女",age=25,looks=20,showequip={},withCorpse=0},rwnpc38={id="rwnpc38",dsc="一个风姿俊朗的白衣公子,他手持一柄折扇，一边摇扇，一边饮酒。",sex="男",age=28,looks=23,showequip={},withCorpse=0},rwnpc39={id="rwnpc39",dsc="面容冷峻的侠士，即使是坐在桌前饮酒，长剑也不曾离手。",sex="男",age=29,looks=21,showequip={},withCorpse=0},rwnpc40={id="rwnpc40",dsc="是捕风神探，朝廷成立捕风卫，便是由他主管，陆千候的得力干将之一。",sex="男",age=35,looks=20,showequip={},withCorpse=0},rwnpc41={id="rwnpc41",dsc="她曾是名镇江湖的花旦，如今却成了武林盟会的管事。略施粉黛的容颜比之二乔也不为过。一颦一蹙，举手投足之间，尽显端庄得体。",sex="女",age=27,looks=24,showequip={},withCorpse=0},rwnpc42={id="rwnpc42",dsc="十二侍从之一，沐言微的兄长。其家族世代都侍奉重光神使。他生得满是书卷之气，举止之间彬彬儒雅，虽然算不得丰神俊朗，但也是气质出尘。",sex="男",age=28,looks=21,showequip={},withCorpse=0},rwnpc43={id="rwnpc43",dsc="是这一代的龙城山庄的主人，他身着淡青长袍，腰系青玉佩，负手而立，容貌俊美，潇洒闲雅。",sex="男",age=25,looks=25,showequip={},withCorpse=0},rwnpc44={id="rwnpc44",dsc="她是慕容业的婢女谢小雅，她生的娇美俏丽，十分可人。",sex="女",age=16,looks=22,showequip={},withCorpse=0},rwnpc45={id="rwnpc45",dsc="雪山四老之一，武功和佛法都已臻大成。",sex="男",age=70,looks=30,showequip={},withCorpse=0},rwnpc46={id="rwnpc46",dsc="是幽冥教教主嫡传弟子，他眼若晨星，眉分八彩，肤色冰白，身穿黑绒白羽袍，脚不着履，颜如舜华，宛若女子一般，但若谁要真当他是个女子好欺，那当真是找死之举。",sex="男",age=29,looks=29,showequip={},withCorpse=0},rwnpc47={id="rwnpc47",dsc="本名杨秋白，是天竞门的第六代掌门。她素日鲜少在门中露面，多半辗转于各大戏楼，且为了唱戏方便，面上常带着花旦妆，故，市井中人只知“百花杀”，极少有人识破她真实身份。",sex="女",age=42,looks=26,showequip={},withCorpse=0}}000000000000